"""GPU regression: hiding an already-back-facing face must not affect visible pixels."""
SCRIPT = r"""const r=window.__morphforge.renderer;r.renderer.setAnimationLoop(null);r.helpers.visible=false;const mesh=r.meshes.find(m=>m.userData.boxes.some(b=>b.group==='water-b'));const style=r.styles.find(m=>m.id===mesh.userData.styleId);const box=mesh.userData.boxes.find(b=>b.group==='water-b')||mesh.userData.boxes[0];r.updateInstances(mesh,[box],style,{full:true});for(const m of r.meshes)m.visible=m===mesh;r.view('hero');r.controls.enableDamping=false;r.controls.update();for(const u of r.uniforms){u.mfTime.value=0;u.mfGrid.value=0;}const attr=mesh.geometry.attributes.mfHiddenFaces;attr.array[0]=2;attr.needsUpdate=true;const gl=r.renderer.getContext(),size={x:r.renderer.domElement.width,y:r.renderer.domElement.height};const capture=(mode)=>{for(const u of r.uniforms)u.mfCull.value=mode;r.render();const p=new Uint8Array(size.x*size.y*4);gl.readPixels(0,0,size.x,size.y,gl.RGBA,gl.UNSIGNED_BYTE,p);return p;};const a=capture(0),b=capture(1);let changed=0;for(let i=0;i<a.length;i+=4)if(a[i]!==b[i]||a[i+1]!==b[i+1]||a[i+2]!==b[i+2])changed++;return {changedPixels:changed,width:size.x,height:size.y,box};"""
def probe(browser):
    return browser.js(SCRIPT)
